prompt.text:
Run this workflow with the Workflow tool, passing it exactly as the script input, unchanged. When it ends, answer me with its result on one line.

export const meta = { name: 'read-two', description: 'Read two small files', phases: [ { title: 'Read', detail: 'read a.txt' }, { title: 'Check', detail: 'cat b.txt' } ] }
phase('Read')
const a = await agent('Read a.txt with the Read tool and return its one line only.', { label: 'read a.txt', effort: 'low' })
phase('Check')
const b = await agent('Run the shell command `cat b.txt` with the Bash tool and return its output only.', { label: 'cat b.txt', effort: 'low' })
log('read both files')
return [a, b].join(' ')

